# 第13课 — WORD_EXPL, COLLOC, WORD_CMP, COMPREHENSION, RETELL, CULTURE, INTRO, WRITING (教案 байхгүй тул агентаар)
def _ch(q, opts, a, ok, wrong): return dict(type="choice", question=q, options=opts, answer=a, ok=ok, wrong=wrong)
def _jd(q, a, ok, wrong): return dict(type="judge", question=q, answer=a, ok=ok, wrong=wrong)

